/* 居中日期：按原生 kind 隐藏今天，保留昨天／星期几／较早日期。
 * 这里没有相邻消息时间差，也不改写原生日期文字；并非精确满 24 小时判断。
 * 气泡旁 .msg-wa-meta 不受影响。
 */
.chat-detail-screen .nj-chat-time { display:block !important; width:100%; box-sizing:border-box; margin:12px 0 10px !important; padding:7px 0 0 !important; border:0 !important; border-top:1px solid var(--b-day-line) !important; border-radius:0 !important; background:transparent !important; box-shadow:none !important; text-align:center !important; color:var(--b-day-text) !important; -webkit-text-fill-color:var(--b-day-text) !important; font:400 10px/15px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif !important; }
.chat-detail-screen .nj-chat-time[data-time-kind="today"] { display:none !important; }


/* ARTIST 承接原生思维链按钮：只在原生按钮存在时覆盖徽章点击区。
 * 不改变头像的心声功能；不新增假数据、不调用 API；展开仍走原生 onClick。
 * 原按钮位于 bubble-deco 内，将其改为 static，定位到消息的 msg-content-stack。
 */
.chat-detail-screen .msg-content-stack:has(.nuo-thinking-btn) { position:relative !important; }
.chat-detail-screen .bubble-deco:has(> .nuo-thinking-wrap) { position:static !important; }
.chat-detail-screen .nuo-thinking-wrap { position:static !important; gap:0 !important; margin:0 !important; padding:0 !important; border:0 !important; background:transparent !important; }
.chat-detail-screen .nuo-thinking-btn { position:absolute !important; top:0 !important; left:0 !important; right:auto !important; bottom:auto !important; width:44px !important; min-width:44px !important; max-width:44px !important; height:14px !important; min-height:14px !important; max-height:14px !important; box-sizing:border-box; margin:0 !important; padding:0 !important; border:0 !important; border-radius:999px !important; background:transparent !important; color:transparent !important; box-shadow:none !important; z-index:5 !important; cursor:pointer; overflow:hidden; }
.chat-detail-screen .nuo-thinking-btn > * { position:absolute !important; width:1px !important; height:1px !important; overflow:hidden !important; clip-path:inset(50%); white-space:nowrap; }
.chat-detail-screen .nuo-thinking-btn::before,
.chat-detail-screen .nuo-thinking-btn::after { display:none !important; }
.chat-detail-screen .msg-content-stack:has(.nuo-thinking-wrap.is-open)::before { box-shadow:0 0 0 2px var(--b-thinking-ring); }
.chat-detail-screen .nuo-thinking-wrap.is-open { display:flex !important; width:100% !important; }
.chat-detail-screen .nuo-thinking-panel { box-sizing:border-box; width:100%; padding:10px 12px !important; margin:0 0 6px !important; border:1px solid var(--b-thinking-border) !important; border-radius:10px !important; background:var(--b-thinking-fallback) !important; background:color-mix(in srgb,var(--b-thinking-bg) var(--b-thinking-opacity),transparent) !important; color:var(--b-other-ink) !important; font:400 12px/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif !important; box-shadow:none !important; backdrop-filter:none !important; animation:bubble-nuo-paper 150ms ease-out; }
@keyframes bubble-nuo-paper { from { opacity:0; transform:translateY(-2px); } to { opacity:1; transform:translateY(0); } }

/* 紧凑语音：使用原生播放/暂停、实际进度条和下载，不创建音频或定时器。 */
.chat-detail-screen .voice-controls-row { box-sizing:border-box !important; width:190px !important; min-width:0 !important; max-width:100% !important; min-height:36.5px !important; padding:8.25px 10px !important; gap:8px !important; }
.chat-detail-screen .voice-play-btn { width:20px !important; height:20px !important; min-width:20px !important; padding:0 !important; border:0 !important; background:transparent !important; box-shadow:none !important; color:inherit !important; }
.chat-detail-screen .voice-play-btn svg { width:18px !important; height:18px !important; stroke-width:1.8; }
.chat-detail-screen .voice-waveform { min-width:0 !important; height:18px !important; gap:2px !important; overflow:hidden; }
.chat-detail-screen .voice-waveform-bar { min-width:1px !important; max-width:3px !important; border-radius:3px !important; transform-origin:center; animation:none; transition:background-color .2s !important; }
.chat-detail-screen .voice-duration { font:400 12px/20px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif !important; }
.chat-detail-screen .voice-download-btn { display:flex !important; color:inherit !important; opacity:.55 !important; width:18px; height:20px; align-items:center; justify-content:center; }
.chat-detail-screen .voice-download-btn svg { width:15px !important; height:15px !important; }
.chat-detail-screen .voice-transcription-toggle { width:fit-content; max-width:100%; align-self:flex-start !important; text-align:left !important; margin:4px 0 0 !important; padding:1px 0 !important; font:400 10px/16px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif !important; color:var(--b-muted) !important; gap:4px !important; }
.chat-detail-screen .msg-me .voice-transcription-toggle { align-self:flex-end !important; }
/* 原生播放中渲染 Pause，暂停后渲染 Play；以实际图标状态控制轻微波形动效。
 * lucide-pause 为原生图标类；双 rect 是同图标旧版本的兼容写法。
 */
.chat-detail-screen .voice-msg:has(.voice-play-btn .lucide-pause) .voice-waveform-bar,
.chat-detail-screen .voice-msg:has(.voice-play-btn svg > rect + rect) .voice-waveform-bar { animation:bubble-nuo-voice 900ms ease-in-out infinite; }
.chat-detail-screen .voice-msg .voice-waveform-bar:nth-child(3n+1) { animation-delay:-300ms; }
.chat-detail-screen .voice-msg .voice-waveform-bar:nth-child(3n+2) { animation-delay:-600ms; }
@keyframes bubble-nuo-voice { 0%,100% { transform:scaleY(.72); } 50% { transform:scaleY(1); } }

/* 长按菜单原生挂在 Portal，不是聊天根节点的子元素。
 * 下列规则仅在本美化的活动聊天室存在时生效；保留全部真实动作和点击空白关闭。
 * 原生没有暴露选中消息坐标，因此操作带固定在输入栏上方，不伪装成精确跟随气泡。
 */
body:has(#chat-detail-screen.active.chat-detail-screen) div:has(> div > .ig-context-menu) { display:block !important; background:transparent !important; backdrop-filter:none !important; }
body:has(#chat-detail-screen.active.chat-detail-screen) div:has(> div > .ig-context-menu) > div:not(:has(> .ig-context-menu)) { display:none !important; }
body:has(#chat-detail-screen.active.chat-detail-screen) div:has(> .ig-context-menu) { position:absolute !important; left:10px !important; right:10px !important; top:auto !important; bottom:calc(66px + var(--nuo-safe-bottom,0px)) !important; width:auto !important; max-width:440px !important; margin:0 auto !important; gap:5px !important; transform:none !important; }
body:has(#chat-detail-screen.active.chat-detail-screen) div:has(> .ig-context-menu) > :not(.reaction-bar,.ig-context-menu) { display:none !important; }
body:has(#chat-detail-screen.active.chat-detail-screen) .ig-context-menu { display:flex !important; flex-direction:row !important; flex-wrap:nowrap !important; align-items:center !important; align-self:center; width:max-content !important; max-width:100% !important; min-width:0 !important; box-sizing:border-box; height:44px; min-height:44px; padding:4px !important; gap:0 !important; overflow-x:auto !important; overflow-y:hidden !important; scrollbar-width:none; overscroll-behavior-x:contain; touch-action:pan-x; border:1px solid var(--b-longpress-border); border-radius:999px !important; background:var(--b-longpress-bg) !important; box-shadow:0 3px 12px var(--b-menu-shadow) !important; backdrop-filter:none !important; animation:bubble-nuo-paper 150ms ease-out; }

/* 只隐藏可见文字，保留原生文字节点与真实操作；不按序号删减功能。 */
body:has(#chat-detail-screen.active.chat-detail-screen) .ig-menu-item { display:flex !important; flex-direction:row !important; align-items:center !important; justify-content:center !important; flex:0 0 36px !important; width:36px !important; min-width:36px !important; height:36px !important; min-height:36px !important; box-sizing:border-box; margin:0 !important; padding:8px !important; gap:0 !important; border:0 !important; border-radius:50%; font-size:0 !important; line-height:0 !important; white-space:nowrap !important; overflow:hidden; }
body:has(#chat-detail-screen.active.chat-detail-screen) .ig-menu-item > :not(svg) { position:absolute !important; width:1px !important; height:1px !important; overflow:hidden; clip-path:inset(50%); }
body:has(#chat-detail-screen.active.chat-detail-screen) .ig-menu-item:not(.danger) { color:var(--b-longpress-ink) !important; }
body:has(#chat-detail-screen.active.chat-detail-screen) .ig-menu-item.danger { color:var(--b-danger) !important; }
body:has(#chat-detail-screen.active.chat-detail-screen) .ig-context-menu::-webkit-scrollbar { display:none; }

body:has(#chat-detail-screen.active.chat-detail-screen) .ig-menu-item svg { display:block !important; width:20px !important; height:20px !important; flex:none; stroke-width:1.7; }
body:has(#chat-detail-screen.active.chat-detail-screen) .ig-context-menu .ig-menu-item:active { background:var(--b-hover) !important; }
body:has(#chat-detail-screen.active.chat-detail-screen) div:has(> .ig-context-menu) > .reaction-bar { align-self:center; width:fit-content !important; max-width:100% !important; padding:5px 9px !important; gap:10px !important; border-radius:10px !important; background:var(--b-chrome) !important; box-shadow:0 2px 10px var(--b-menu-shadow) !important; }
body:has(#chat-detail-screen.active.chat-detail-screen) .reaction-bar .reaction-item { font-size:20px !important; line-height:26px !important; padding:0 !important; }

/* 多选工具栏没有专用 class；按原生两组结构识别，避免命中正常输入框。
 * 顶部：真实选中数与取消；下方：全部操作均分，不删减原生功能。
 */
.chat-detail-screen .chat-input-area-root > div:has(> div > button > div > svg):has(> div > span + button) {
  display:flex !important; flex-direction:column !important; align-items:stretch !important;
  justify-content:flex-start !important; gap:5px !important; height:auto !important;
  min-width:0; width:100%; box-sizing:border-box; padding:0 !important;
  color:var(--b-ink); font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
}
.chat-detail-screen .chat-input-area-root > div:has(> div > button > div > svg):has(> div > span + button) > div:first-child {
  display:flex !important; flex-direction:row !important; align-items:stretch !important;
  justify-content:space-around !important; gap:0 !important; min-width:0; width:100%;
  border-top:1px solid var(--b-divider); padding-top:5px; box-sizing:border-box;
}
.chat-detail-screen .chat-input-area-root > div:has(> div > button > div > svg):has(> div > span + button) > div:last-child {
  order:-1; display:flex !important; align-items:center !important; justify-content:space-between !important;
  flex-wrap:nowrap !important; gap:12px !important; min-width:0; min-height:26px; padding:0 6px;
}
.chat-detail-screen .chat-input-area-root > div:has(> div > button > div > svg):has(> div > span + button) > div:last-child > span {
  min-width:0; color:var(--b-selection-accent) !important; font-size:11px !important;
  font-weight:500 !important; line-height:24px !important; white-space:nowrap !important;
}
.chat-detail-screen .chat-input-area-root > div:has(> div > button > div > svg):has(> div > span + button) > div:last-child > button {
  flex:none; padding:3px 8px !important; border:0 !important; border-radius:12px;
  color:var(--b-selection-accent) !important; background:var(--b-field) !important;
  font-size:11px !important; font-weight:500 !important; line-height:20px !important; white-space:nowrap !important;
}
.chat-detail-screen .chat-input-area-root > div:has(> div > button > div > svg):has(> div > span + button) > div:first-child > button {
  flex:1 1 0 !important; min-width:0 !important; width:auto !important; max-width:70px;
  box-sizing:border-box; min-height:44px; margin:0 !important; padding:4px 1px !important;
  border:0 !important; border-radius:10px; background:transparent !important;
  font-family:inherit; -webkit-tap-highlight-color:transparent;
}
.chat-detail-screen .chat-input-area-root > div:has(> div > button > div > svg):has(> div > span + button) > div:first-child > button > div {
  display:flex !important; flex-direction:column !important; align-items:center !important;
  justify-content:center !important; gap:4px !important; width:100%; min-width:0;
}
.chat-detail-screen .chat-input-area-root > div:has(> div > button > div > svg):has(> div > span + button) > div:first-child > button svg {
  display:block; flex:none; width:19px !important; height:19px !important; stroke-width:1.7;
}
.chat-detail-screen .chat-input-area-root > div:has(> div > button > div > svg):has(> div > span + button) > div:first-child > button span {
  display:block; font-size:10px !important; font-weight:400 !important; line-height:14px !important;
  white-space:nowrap !important; word-break:normal !important;
}
.chat-detail-screen .chat-input-area-root > div:has(> div > button > div > svg):has(> div > span + button) button:active { opacity:.65; }
.chat-detail-screen .chat-input-area-root > div:has(> div > button > div > svg):has(> div > span + button) button:disabled { opacity:.4; }
/* 使用真实勾选状态，去掉 CheckCircle2 自带外圈造成的双圈。 */
.chat-detail-screen .nuo-selection-checkbox { left:0 !important; width:28px !important; }
.chat-detail-screen .nuo-selection-checkbox > div {
  display:grid !important; place-items:center; width:18px !important; height:18px !important;
  box-sizing:border-box; border:1.5px solid var(--b-selection-border) !important; background:var(--b-selection-bg) !important;
  border-radius:50%; box-shadow:none !important;
}
.chat-detail-screen .nuo-selection-checkbox > div:has(svg) { border-color:var(--b-selection-accent) !important; background:var(--b-selection-accent) !important; }
.chat-detail-screen .nuo-selection-checkbox svg { display:none !important; }
.chat-detail-screen .nuo-selection-checkbox > div:has(svg)::after { content:""; width:10px; height:10px; background:var(--b-selection-check); -webkit-mask:url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%3E%3Cpath%20d%3D%22m5%2012%204%204L19%206%22%20fill%3D%22none%22%20stroke%3D%22black%22%20stroke-width%3D%222.7%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%2F%3E%3C%2Fsvg%3E") center / contain no-repeat; mask:url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%3E%3Cpath%20d%3D%22m5%2012%204%204L19%206%22%20fill%3D%22none%22%20stroke%3D%22black%22%20stroke-width%3D%222.7%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%2F%3E%3C%2Fsvg%3E") center / contain no-repeat; }
/* 保留原生“选到这里”的范围选择，只压低视觉存在感。 */
.chat-detail-screen #chat-message-list-root > div[style*="sticky"]:has(> div > span + span) > div {
  color:var(--b-selection-accent) !important; font-size:10px !important; line-height:18px;
  padding:3px 9px !important; background:var(--b-chrome) !important;
  border:1px solid var(--b-divider); border-radius:999px !important; box-shadow:0 1px 5px var(--b-divider) !important;
}

@media (max-width:360px) {
  .chat-detail-screen { --b-card-width:220px; }
  .chat-detail-screen .msg-transfer-card::before,
  .chat-detail-screen .msg-gift-card::before { font-size:24px; padding-right:83px; }
  .chat-detail-screen .msg-transfer-card::after,
  .chat-detail-screen .msg-gift-card::after { width:68px; right:16px; }
}
@media (prefers-reduced-motion:reduce) {
  .chat-detail-screen .chat-messages-area,
  .chat-detail-screen .more-options-popup,
  .chat-detail-screen .chat-header-custom > .chat-header-deco-2,
  .chat-detail-screen .more-options-item-row,
  .chat-detail-screen .more-options-meta-row > span:first-child::before { transition:none !important; animation:none !important; }
  #chat-detail-screen.chat-detail-screen .chat-messages-area,
  #chat-detail-screen.chat-detail-screen .chat-message-list-custom { transition:none !important; }
  #chat-detail-screen.chat-detail-screen .stop-btn-custom::before,
  #chat-detail-screen.chat-detail-screen .input-btn-ai::before,
  .chat-detail-screen .nuo-typing-indicator .typing-dot,
  .chat-detail-screen .msg-wa-checks.read { animation:none !important; }
}

@media (prefers-reduced-motion:reduce) {
  #chat-detail-screen.chat-detail-screen::after { transition:none !important; }
  .chat-detail-screen .nuo-thinking-panel,
  .chat-detail-screen .voice-msg .voice-waveform-bar,
  body:has(#chat-detail-screen.active.chat-detail-screen) .ig-context-menu { animation:none !important; }
}

@media (prefers-reduced-motion:reduce) {
  #chat-detail-screen.chat-detail-screen #chat-message-list-root.chat-message-list-custom { transition:none !important; }
}

@media (prefers-reduced-motion:reduce) {
  .chat-detail-screen:has(.more-options-popup) :is(.header-btn-info,.header-btn-phone,.header-btn-video,.input-btn-mic) { animation:none !important; }
}

