/* 对方转账卡、红包卡 */
.msg-them .msg-transfer-card,
.msg-them .msg-redpacket-card {
  display: block !important;
}

/* 对方通话卡 */
.msg-them .msg-videocall-card {
  display: flex !important;
}

/* 对方转账卡、红包卡文字颜色 */
.msg-them .msg-transfer-card *,
.msg-them .msg-redpacket-card * {
  color: #535353 !important;
}

/* 外层：只负责排版 */
.input-row-wrapper {
  position: relative !important;
  display: flex !important;
  flex-wrap: wrap !important;
  align-items: center !important;
  justify-content: center !important;
  padding: 0 !important;
  border: none !important;
  overflow: visible !important;
}

/* 中间两层容器溶解，按钮直接参与外层排版 */
.input-action-bar-custom,
.input-btns-right {
  display: contents !important;
}

/* 第一行输入框独占一行 */
.input-row-wrapper #chat-message-input {
  order: -1 !important;
  flex: 0 0 100% !important;
  box-sizing: border-box !important;
  min-height: 4px !important;
  padding: 10px 52px 10px 16px !important;
}

/* 发送 / 停止：浮在输入框右侧里面 */
.send-btn-custom,
.stop-btn-custom {
  position: absolute !important;
  right: 10px !important;
  top: 6px !important;
  z-index: 2 !important;
}

/* 第二行按钮排序 */
.input-btn-mic     { order: 1 !important; }
.input-btn-ai      { order: 4 !important; }
.input-btn-sticker { order: 5 !important; }
.input-btn-plus    { order: 6 !important; }

/* 按钮透明背景 */
.input-btn-plus,
.input-btn-mic,
.input-btn-sticker,
.input-btn-ai {
  background: transparent !important;
  margin-left: 0 !important;
  position: relative !important;
  z-index: 1 !important;
}

/* 新增两个伪元素，占第2、3位 —— 换成实际图片链接 */
.input-row-wrapper::before,
.input-row-wrapper::after {
  content: "" !important;
  display: block !important;
  width: 32px !important;
  height: 32px !important;
  background: url('https://example.com/替换成你的图1.png') no-repeat center / contain !important;
  position: relative !important;
  z-index: 1 !important;
}

/* 伪元素1排第 2 位 */
.input-row-wrapper::before {
  order: 2 !important;
}

/* 伪元素2排第 3 位 */
.input-row-wrapper::after {
  order: 3 !important;
  background-image: url('https://example.com/替换成你的图2.png') !important;
}

/* 输入框颜色 */
.input-row-wrapper #chat-message-input,
.input-row-wrapper #chat-message-input:focus,
.input-row-wrapper #chat-message-input:focus-visible,
.input-row-wrapper #chat-message-input:active {
  background: #636363 !important;
  background-color: #636363 !important;
  border: none !important;
  border-radius: 10px !important;
  box-shadow: inset 3px 3px 3px rgba(30,30,30,0.8) !important;
  outline: none !important;
  color: #c9c9c9 !important;
  -webkit-text-fill-color: #c9c9c9 !important;
  caret-color: #c9c9c9 !important;
}

/* 占位符隐藏 */
.input-box-custom::placeholder,
.input-box-custom textarea::placeholder {
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  opacity: 0 !important;
}

/* 发送按钮图标颜色 */
.input-row-wrapper .send-btn-custom,
.input-row-wrapper .send-btn-custom svg,
.input-row-wrapper .send-btn-custom svg * {
  color: #c9c9c9 !important;
  stroke: #c9c9c9 !important;
}

/* 控制台 */
.nuo-console-shell {
  --console-toggle-color: #cacaca;
    --console-toggle-bg: transparent;
  --console-token-bg: transparent;
  --console-token-shadow: none;
  --console-token-color: #cacaca;
}

/* 底栏容器 */
.chat-input-area-root {
  background-image: url('https://s3.bmp.ovh/2026/10/16/SARkq2Qm.png') !important;
  background-size: cover !important; 
  background-position: 50% 0% !important; 
  background-repeat: no-repeat !important; 
  border: none !important; 
}

/* 第二行背景图 */
.input-row-wrapper {
  background-color: transparent !important;
  background-image: url("https://s3.bmp.ovh/2026/10/16/PGT3foNg.png") !important;
  background-repeat: no-repeat !important;
  background-position: center bottom !important;
  background-size: 125% 40px !important;
}

/* 隐藏原按钮但保留可点击 */
.input-btn-plus,
.input-btn-mic,
.input-btn-ai,
.input-btn-sticker {
  opacity: 0 !important;
  pointer-events: auto !important;
}

/* 底栏按钮间距 */
.input-row-wrapper {
  row-gap: 8px !important;
  column-gap: 9% !important;
}
